import{_ as r,C as a,o as s,c as n,j as o,a as t,G as l,a2 as c}from"./chunks/framework.BgSoyxN5.js";const b=JSON.parse('{"title":"About TickerForge | Stock & Portfolio Intelligence Platform","description":"Learn about TickerForge, an independent stock and portfolio intelligence platform built for structured research, portfolio diagnostics, market context, and risk monitoring.","frontmatter":{"title":"About TickerForge | Stock & Portfolio Intelligence Platform","description":"Learn about TickerForge, an independent stock and portfolio intelligence platform built for structured research, portfolio diagnostics, market context, and risk monitoring."},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1785053778000}'),d={name:"about.md"};function h(u,e,p,g,k,f){const i=a("TickerForgeTrustBlock");return s(),n("div",null,[e[0]||(e[0]=o("h1",{id:"about-tickerforge",tabindex:"-1"},[t("About TickerForge "),o("a",{class:"header-anchor",href:"#about-tickerforge","aria-label":'Permalink to "About TickerForge"'},"​")],-1)),e[1]||(e[1]=o("p",null,[o("strong",null,"TickerForge"),t(" is an independent stock and portfolio intelligence platform for investors who want to check the story before they trust the story.")],-1)),e[2]||(e[2]=o("p",null,"We do not build trading bots. We do not sell price predictions. TickerForge is built to help investors move from hype-driven decisions to structured stock research, portfolio diagnostics, and risk-aware monitoring.",-1)),e[3]||(e[3]=o("p",null,"The core idea is simple:",-1)),e[4]||(e[4]=o("blockquote",null,[o("p",null,[t("Good investing is not only about finding exciting stocks."),o("br"),t(" It is about checking whether the business, market behavior, smart money, insider activity, portfolio risk, and timing still support the thesis.")])],-1)),l(i,{kind:"platform"}),e[5]||(e[5]=c('<hr><h2 id="what-tickerforge-helps-you-do" tabindex="-1">What TickerForge Helps You Do <a class="header-anchor" href="#what-tickerforge-helps-you-do" aria-label="Permalink to &quot;What TickerForge Helps You Do&quot;">​</a></h2><p>TickerForge combines stock diagnostics, portfolio tools, and market context into one research workflow.</p><h3 id="stock-research" tabindex="-1">Stock research <a class="header-anchor" href="#stock-research" aria-label="Permalink to &quot;Stock research&quot;">​</a></h3><p>Use TickerForge to review individual companies through structured diagnostics instead of relying only on headlines or social-media narratives.</p><p>Start here:</p><ul><li><a href="/stock-widget">Stock Check Widget</a> — run a structured diagnostic for a ticker.</li><li><a href="/stocks/">AI Stock Deep Dives</a> — read curated analysis of high-momentum and AI-infrastructure stocks.</li><li><a href="/methodology/tickerforge-score">Stock Score &amp; Valuation Methodology</a> — see how TickerForge evaluates stock quality and valuation context.</li><li><a href="/methodology/risk-score">Stock Risk Score</a> — understand how risk signals are evaluated.</li></ul><h3 id="portfolio-diagnostics" tabindex="-1">Portfolio diagnostics <a class="header-anchor" href="#portfolio-diagnostics" aria-label="Permalink to &quot;Portfolio diagnostics&quot;">​</a></h3><p>A stock can look attractive in isolation and still make a portfolio weaker. TickerForge helps investors check concentration, exposure, stress scenarios, and portfolio health.</p><p>Start here:</p><ul><li><a href="/import-portfolio">Import Portfolio</a> — analyze your own holdings and cash.</li><li><a href="/portfolio-diagnostics">Portfolio Diagnostics Demo</a> — compare live model portfolios.</li><li><a href="/portfolio-builder">Portfolio Builder</a> — build a rules-based virtual portfolio.</li><li><a href="/portfolio-analysis">Portfolio Analysis Reports</a> — see the full portfolio diagnostic workflow.</li><li><a href="/methodology/portfolio-health-check">Portfolio Health Check Methodology</a> — understand the portfolio health score.</li><li><a href="/methodology/portfolio-stress-test">Portfolio Stress Test Methodology</a> — review downside, upside, beta, and margin-risk logic.</li></ul><h3 id="market-context" tabindex="-1">Market context <a class="header-anchor" href="#market-context" aria-label="Permalink to &quot;Market context&quot;">​</a></h3><p>TickerForge also looks at the market environment around a stock or portfolio. Market regime, market stress, and sector rotation can change whether a good idea is still a good setup.</p><p>Explore:</p><ul><li><a href="/methodology/decoding-market-regimes">Market Regime</a></li><li><a href="/methodology/market-stress-index">Market Stress Index</a></li><li><a href="/methodology/sector-rotation">Sector Rotation</a></li></ul><hr><h2 id="why-tickerforge-exists" tabindex="-1">Why TickerForge Exists <a class="header-anchor" href="#why-tickerforge-exists" aria-label="Permalink to &quot;Why TickerForge Exists&quot;">​</a></h2><p>Retail investors often get strong narratives before they get strong evidence.</p><p>A stock becomes an “AI winner.” A portfolio feels diversified. A chart looks strong. A headline sounds important. But without a structured process, it is easy to confuse a good story with a good setup.</p><p>TickerForge was built to make that process more disciplined.</p><p>Instead of asking only:</p><blockquote><p>“Will this stock go up?”</p></blockquote><p>TickerForge helps ask better questions:</p><ul><li>Is the business quality improving or weakening?</li><li>Are quarterly trends confirming the thesis?</li><li>Is the stock’s timing still constructive?</li><li>Are risk signals rising after a large move?</li><li>Are insiders, funds, and market context still supportive?</li><li>Does this stock improve the portfolio or increase hidden concentration?</li><li>What changes would weaken the thesis?</li></ul><p>This is why TickerForge focuses on diagnostics, alerts, and structured decision support rather than one-line predictions.</p><hr><h2 id="the-engineering-mindset" tabindex="-1">The Engineering Mindset <a class="header-anchor" href="#the-engineering-mindset" aria-label="Permalink to &quot;The Engineering Mindset&quot;">​</a></h2><p>TickerForge applies systems-engineering thinking to investing.</p><p>In technology, you do not trust a complex system just because it looks fine on the surface. You monitor it. You test it. You check failure modes. You look for weak signals before the system breaks.</p><p>Investing should work the same way.</p><p>TickerForge is designed around that mindset:</p><ul><li><strong>Observability:</strong> make stock and portfolio risk visible.</li><li><strong>Diagnostics:</strong> separate business reality from market narrative.</li><li><strong>Stress testing:</strong> estimate how portfolios may behave under market shocks.</li><li><strong>Alerts:</strong> monitor timing changes, quarterly deterioration, risk signals, and thesis breaks.</li><li><strong>Decision architecture:</strong> give investors a repeatable process instead of emotional guessing.</li></ul><p>TickerForge does not remove uncertainty. It helps investors manage it more deliberately.</p><hr><h2 id="what-makes-tickerforge-different" tabindex="-1">What Makes TickerForge Different <a class="header-anchor" href="#what-makes-tickerforge-different" aria-label="Permalink to &quot;What Makes TickerForge Different&quot;">​</a></h2><p>TickerForge is not just another stock screener.</p><p>It combines several layers of analysis:</p><ul><li>business and financial diagnostics;</li><li>stock risk scoring;</li><li>valuation and quality context;</li><li>technical timing;</li><li>insider activity;</li><li>13F fund behavior;</li><li>market regime and market stress;</li><li>sector rotation;</li><li>portfolio health checks;</li><li>portfolio stress testing;</li><li>stock and portfolio alerts.</li></ul><p>The goal is not to produce a magic answer. The goal is to show whether the evidence still supports the thesis.</p><hr><h2 id="built-for-independent-investors" tabindex="-1">Built for Independent Investors <a class="header-anchor" href="#built-for-independent-investors" aria-label="Permalink to &quot;Built for Independent Investors&quot;">​</a></h2><p>TickerForge is designed for investors who want more structure without needing an institutional terminal.</p><p>It is especially useful for:</p><ul><li>investors researching high-momentum stocks;</li><li>people tracking AI, semiconductor, data-center, and infrastructure themes;</li><li>investors comparing individual stock ideas before adding them to a portfolio;</li><li>portfolio builders who want to avoid hidden concentration;</li><li>users who want alerts when timing, quarterly data, or business quality starts to weaken.</li></ul><p>TickerForge is research software. It is not a broker, advisor, or trading signal service.</p><hr><h2 id="founder" tabindex="-1">Founder <a class="header-anchor" href="#founder" aria-label="Permalink to &quot;Founder&quot;">​</a></h2><p>TickerForge was created by <strong>Anton Tkach</strong>, a solutions engineer with more than 20 years of experience in IT infrastructure, monitoring, systems integration, and data-driven technical decision support across APAC and EMEA.</p><p>The product grew from the same principle used in infrastructure engineering:</p><blockquote><p>Complex systems should be monitored, tested, and diagnosed before critical decisions are made.</p></blockquote><p>TickerForge brings that mindset to stock research and portfolio management.</p><hr><h2 id="contact-links" tabindex="-1">Contact &amp; Links <a class="header-anchor" href="#contact-links" aria-label="Permalink to &quot;Contact &amp; Links&quot;">​</a></h2><p>Use these links to follow the project, try the tools, or connect with the founder.</p><h3 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h3><ul><li><a href="https://t.me/TickerForgeBot?start=src_about" target="_blank" rel="noreferrer">Launch TickerForge in Telegram</a></li><li><a href="/stock-widget">Check a Stock</a></li><li><a href="/import-portfolio">Import Portfolio</a></li><li><a href="/pricing">Pricing</a></li><li><a href="/faq">FAQ</a></li></ul><h3 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h3><ul><li><a href="/stocks/">AI Stock Deep Dives</a></li><li><a href="/blog/">Blog</a></li><li><a href="/guides/how-to-track-smart-money">Guides</a></li><li><a href="https://t.me/+Cm30octtKYMxZWRi" target="_blank" rel="noreferrer">Market News Channel</a></li></ul><h3 id="social" tabindex="-1">Social <a class="header-anchor" href="#social" aria-label="Permalink to &quot;Social&quot;">​</a></h3><ul><li><a href="https://www.linkedin.com/company/tickerforge/" target="_blank" rel="noreferrer">TickerForge on LinkedIn</a></li><li><a href="https://www.instagram.com/tickerforge.ai/" target="_blank" rel="noreferrer">TickerForge on Instagram</a></li><li><a href="https://linkedin.com/in/antontkatch" target="_blank" rel="noreferrer">Founder LinkedIn</a></li><li><a href="https://github.com/BusyDizzy" target="_blank" rel="noreferrer">Founder GitHub</a></li></ul><hr><h2 id="important-disclaimer" tabindex="-1">Important Disclaimer <a class="header-anchor" href="#important-disclaimer" aria-label="Permalink to &quot;Important Disclaimer&quot;">​</a></h2><p>TickerForge is for informational and educational purposes only. It does not provide personalized investment advice, financial planning, brokerage services, or guaranteed outcomes.</p><p>Markets involve risk. Stock diagnostics, alerts, portfolio stress tests, and market-regime signals are decision-support tools, not predictions or instructions to buy or sell securities.</p>',64))])}const y=r(d,[["render",h]]);export{b as __pageData,y as default};
